// Verifies X-SSS-Signature = sha256=HMAC_SHA256(secret, timestamp + '.' + rawBody) and rejects stale timestamps.
// Needs NODE_FUNCTION_ALLOW_BUILTIN=crypto and SSS_WEBHOOK_SECRET in the n8n environment.
const crypto = require('crypto');
const out = [];
for (const item of $input.all()) {
  const h = item.json.headers || {};
  const ts = String(h['x-sss-timestamp'] || '');
  const raw = item.binary && item.binary.data ? Buffer.from(item.binary.data.data, 'base64').toString('utf8') : JSON.stringify(item.json.body);
  const expected = 'sha256=' + crypto.createHmac('sha256', $env.SSS_WEBHOOK_SECRET).update(ts + '.' + raw).digest('hex');
  const given = String(h['x-sss-signature'] || '');
  const fresh = Math.abs(Date.now() / 1000 - Number(ts)) < 300;
  const valid = fresh && given.length === expected.length && crypto.timingSafeEqual(Buffer.from(given), Buffer.from(expected));
  out.push({ json: { valid, event: h['x-sss-event'], delivery: h['x-sss-delivery'], payload: valid ? JSON.parse(raw) : null } });
}
return out;
